import{z as s,x as i,o as B,c as p,q as o,j as r,D as E,d as t,s as l,S as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"正则与丢弃的取舍","description":"","frontmatter":{"title":"正则与丢弃的取舍","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-regularization-dropout.md","filePath":"llm/pf2-regularization-dropout.md","lastUpdated":1791063341000}'),n={name:"llm/pf2-regularization-dropout.md"};function d(m,a,h,u,C,F){const e=i("Mermaid");return B(),p("div",null,[a[2]||(a[2]=o('<h1 id="正则与丢弃的取舍" tabindex="-1">正则与丢弃的取舍 <a class="header-anchor" href="#正则与丢弃的取舍" aria-label="Permalink to &quot;正则与丢弃的取舍&quot;">​</a></h1><div class="epigraph"><p>当数据远大于模型容量，正则的任务不再是防止过拟合，而是控制尺度与稳定训练；把教科书默认值抄进预训练，多半是错的。</p><footer>—— 据 Gopher（Rae et al., 2021）与 Llama 系列的预训练设定对照 Srivastava et al., JMLR 2014 整理</footer></div><p><a href="/llm/pf2-lr-warmup-practice">上一课</a>签下日程契约，本课处理正则面的取舍：预训练里 dropout 开不开、权重衰减给谁、z-loss 算不算正则。<a href="/llm/dropout-transformer">dropout 在 Transformer 里的位置</a>与<a href="/llm/weight-decay-exemptions">衰减的豁免清单</a>各有专课，本课把它们放进同一张取舍表：每一项正则力作用在哪个对象上、预训练为什么大多关小、微调为什么又开回来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书默认值在预训练里会反向出错。dropout \\(p=0.1\\) 来自监督数据远小于模型的年代：正则防的是记住训练集。预训练是 token 数远超容量的欠拟合体制，dropout 在这里不防过拟合，只降低每个 step 的有效容量与 token 效率——同样的算力学得更少，公开配方普遍取 \\(p=0\\) 是这个经济学的结果，不是疏忽。权重衰减的方向相反：不能因为「大数据」就全局开大，\\(\\lambda\\) 对归一化增益与嵌入长尾是错误的尺度先验，一个全局 \\(\\lambda\\) 会悄悄压死词表的低频行。取舍问题因此是逐项的：每个正则力要对得上一个具体对象。</p><p><span class="marginnote">「欠拟合体制」是说模型还没把数据学完：token 数远大于模型容量，「记住训练集」这种过拟合病在这时几乎不发生。教科书里防过拟合的药，自然也就不对症。</span></p><h3 id="三条力的分工" tabindex="-1">三条力的分工 <a class="header-anchor" href="#三条力的分工" aria-label="Permalink to &quot;三条力的分工&quot;">​</a></h3><p>把预训练在用的正则力分成三类。<strong>容量类</strong>：dropout、drop-path——只在数据受限或参数远大于 token 时启用；微调小数据时再开回来扫。<strong>尺度类</strong>：权重衰减（按参数组豁免）、<a href="/llm/z-loss">z-loss</a>——衰减给矩阵参数收缩先验，norm 与 bias 豁免，z-loss 钉住 logits 的绝对尺度保护半精度与门控。<strong>稳定性类</strong>：梯度裁剪、QK-Norm——它们不是正则，但常被当成正则调；裁剪是保险丝不是分类器，见<a href="/llm/grad-clip-loss-spike">裁剪与尖峰</a>。</p>',8)),(B(),r(A,null,{default:E(()=>[l(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%AD%A3%E5%88%99%E5%8F%96%E8%88%8D%22%5D%20--%3E%20A%5B%22%E5%AE%B9%E9%87%8F%E7%B1%BB%EF%BC%9Adropout%20%2F%20drop-path%22%5D%0A%20%20R%20--%3E%20B%5B%22%E5%B0%BA%E5%BA%A6%E7%B1%BB%EF%BC%9A%E5%88%86%E7%BB%84%E8%A1%B0%E5%87%8F%20%2B%20z-loss%22%5D%0A%20%20R%20--%3E%20C%5B%22%E7%A8%B3%E5%AE%9A%E6%80%A7%E7%B1%BB%EF%BC%9A%E8%A3%81%E5%89%AA%20%2F%20QK-Norm%22%5D%0A%20%20A%20--%3E%7C%E9%A2%84%E8%AE%AD%E7%BB%83%20token%20%E8%BF%9C%E8%B6%85%E5%AE%B9%E9%87%8F%7C%20A0%5B%22%E9%BB%98%E8%AE%A4%E5%85%B3%E9%97%AD%22%5D%0A%20%20A%20--%3E%7C%E5%BE%AE%E8%B0%83%E5%B0%8F%E6%95%B0%E6%8D%AE%7C%20A1%5B%22%E9%87%8D%E6%96%B0%E5%90%AF%E7%94%A8%E5%B9%B6%E6%89%AB%E6%8F%8F%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%9B%9B%E7%BB%84%E5%8F%82%E6%95%B0%E5%88%86%E5%88%AB%E5%AE%9A%20%CE%BB%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E5%B8%B8%E5%BC%80%EF%BC%8C%E9%98%88%E5%80%BC%E5%8D%95%E7%8B%AC%E6%B6%88%E8%9E%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配方落地四条。第一，dropout 在预训练配置里显式写 \\(p=0\\) 并注明是决定，不是遗漏——否则复现者会以为是漏抄。第二，权重衰减按<a href="/llm/weight-decay-exemptions">四组参数</a>分开写：矩阵、嵌入、输出头、norm 与 bias；验证不看「配置里写了多少」，看各参数组的范数分位数是否符合预期尺度。第三，衰减与学习率通过 \\(\\eta\\lambda\\) 耦合，日程降温时有效收缩率跟着变；这条耦合在<a href="/llm/weight-decay-mup">衰减与 μP</a> 的口径下随宽度如何挂，要小网格验证而不是背口诀。第四，z-loss 系数按词表规模定，词表变化不照抄小词表的数；它与衰减是两条独立的尺度力，要能单独开关。</p><p><span class="marginnote">Transformer 的默认 dropout 打在残差增量与嵌入之后，不打在 Pre-LN 的主干通路上——位置本身就是设计：主干公路承载恒等映射，往上面丢噪声会同时放大深度方向的方差。</span></p><p><span class="marginnote">数字实例：若 \\(\\lambda=0.1\\)、峰值学习率 \\(\\eta=3\\times 10^{-4}\\)，每步有效收缩率约 \\(3\\times 10^{-5}\\)；日程后期 \\(\\eta\\) 降到近零，同一 \\(\\lambda\\) 的收缩力也跟着趋零——所以「衰减恒定」其实是错觉，它随日程一起降温。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么预训练的正则取舍偏向「关容量、留尺度」：欠拟合体制下，容量类正则的边际收益为负——它换掉的是本可以学到的规律；尺度类正则的收益为正——数值稳定与尺度受控是长训练的生存条件。微调体制恰好反转：数据小、更新步数少，过拟合重新成为主要风险，dropout 的随机性重新变成有效的方差缩减。为什么衰减要分组而不全局：\\(\\lambda\\) 隐含「参数应向零收缩」的先验，这个先验对矩阵参数成立（小权重对应平滑函数），对归一化增益（本就该围绕 1）和长尾嵌入（低频词行不更新，衰减会让它沉向死区）不成立——全局 \\(\\lambda\\) 是把一个先验强加给了异质对象。</p><p><span class="marginnote">常见误区：初学者容易把 dropout 当成「普遍有益的健康习惯」到处加。实际上它是一笔「用容量换方差」的交易：数据充足时你卖出容量却拿不到收益，只有数据稀缺时这笔交易才划算。</span></p>',7)),(B(),r(A,null,{default:E(()=>[l(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E7%BB%84%E6%AD%A3%E5%88%99%E5%8A%9B%EF%BC%9A%E4%BD%93%E5%88%B6%E5%8F%98%E4%BA%86%EF%BC%8C%E7%BB%93%E8%AE%BA%E5%8F%8D%E8%BD%AC%22%5D%20--%3E%20P%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%EF%BC%9Atoken%20%E8%BF%9C%E8%B6%85%E5%AE%B9%E9%87%8F%22%5D%0A%20%20Q%20--%3E%20FT%5B%22%E5%BE%AE%E8%B0%83%EF%BC%9A%E6%95%B0%E6%8D%AE%E5%B0%8F%E3%80%81%E6%AD%A5%E6%95%B0%E5%B0%91%22%5D%0A%20%20P%20--%3E%20P1%5B%22%E4%B8%BB%E8%A6%81%E9%A3%8E%E9%99%A9%EF%BC%9A%E6%95%B0%E5%80%BC%E5%B0%BA%E5%BA%A6%E4%B8%8D%E7%A8%B3%22%5D%0A%20%20P%20--%3E%20P2%5B%22%E5%AE%B9%E9%87%8F%E7%B1%BB%20dropout%EF%BC%9A%E6%94%B6%E7%9B%8A%E4%B8%BA%E8%B4%9F%EF%BC%8C%E9%BB%98%E8%AE%A4%E5%85%B3%22%5D%0A%20%20FT%20--%3E%20F1%5B%22%E4%B8%BB%E8%A6%81%E9%A3%8E%E9%99%A9%EF%BC%9A%E8%BF%87%E6%8B%9F%E5%90%88%22%5D%0A%20%20FT%20--%3E%20F2%5B%22%E5%AE%B9%E9%87%8F%E7%B1%BB%20dropout%EF%BC%9A%E6%9C%89%E6%95%88%E6%96%B9%E5%B7%AE%E7%BC%A9%E5%87%8F%EF%BC%8C%E9%87%8D%E6%96%B0%E5%BC%80%E6%89%AB%22%5D%0A%20%20P1%20--%3E%20S%5B%22%E5%B0%BA%E5%BA%A6%E7%B1%BB%EF%BC%88%E5%88%86%E7%BB%84%E8%A1%B0%E5%87%8F%20%2F%20z-loss%EF%BC%89%EF%BC%9A%E5%B8%B8%E5%BC%80%22%5D%0A%20%20F1%20--%3E%20S%0A%20%20P2%20--%3E%20Z%5B%22%E5%90%8C%E4%B8%80%E6%97%8B%E9%92%AE%EF%BC%8C%E4%B8%A4%E5%A5%97%E9%BB%98%E8%AE%A4%E5%80%BC%22%5D%0A%20%20F2%20--%3E%20Z%0A%20%20S%20--%3E%20Z%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p>这张图回答的是「为什么同一组旋钮在预训练与微调里默认值相反」：风险结构变了，每类正则力的收益符号跟着翻转，照抄任何一边的默认值都会错。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲优化器本身：<a href="/llm/adamw">AdamW</a> 的解耦机制、<a href="/llm/muon">Muon</a> 的谱视角是各自的主题。数据侧的「正则」——去重减少记忆、去污防泄漏——不叫正则，它们是数据工程课的口径，不要混进这张取舍表。z-loss 与 <a href="/llm/z-loss-moe">MoE 路由 z-loss</a> 是两个对象，本课只钉词表侧。最后，取舍表随体制移动：数据耗尽被迫进入重复体制时，容量类正则的权衡要重新打开——那是数据耗尽一课的事，这里只留指针。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预训练是 token 远超容量的欠拟合体制：容量类正则默认关，dropout 显式写 \\(p=0\\)。</li><li>尺度类正则常开：衰减按四组参数分别定，norm 与 bias 豁免；z-loss 钉 logits 尺度。</li><li>裁剪与 QK-Norm 是稳定件不是正则，常开但单独消融。</li><li>微调小数据体制反转：dropout 重新启用并扫描。</li><li>出处：Srivastava et al., JMLR 2014；Loshchilov &amp; Hutter, AdamW, ICLR 2019；Gopher（Rae et al., 2021）与 PaLM 的预训练正则设定。</li></ul>',5))])}const _=s(n,[["render",d]]);export{f as __pageData,_ as default};
